-- Official Calapan reference data only. No operational shortage, stock or delivery records.
-- PSA 2024 POPCEN reference date: 2024-07-01. Full provenance: public/data/sources.json.
begin;
on conflict (psgc) do update set name=excluded.name,population=excluded.population,households=excluded.households,household_population=excluded.household_population,reference_date=excluded.reference_date,source_url=excluded.source_url,lat=excluded.lat,lng=excluded.lng,coordinate_source=excluded.coordinate_source,coordinate_accuracy=excluded.coordinate_accuracy,metadata=excluded.metadata;
do $$ begin if (select count(*) from public.agos_barangays) <> 62 or (select sum(population) from public.agos_barangays) <> 148558 or (select sum(household_population) from public.agos_barangays) <> 148031 or (select sum(households) from public.agos_barangays) <> 37833 then raise exception 'Calapan reference totals do not match official PSA counts'; end if; end $$;
commit;
select count(*) as barangays,sum(population) as population,sum(household_population) as household_population,sum(households) as households from public.agos_barangays;
